import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.BF53ZjCA.js";const f=JSON.parse('{"title":"Play of Color","description":"","frontmatter":{"title":"Play of Color","phenomenon":"play-of-color"},"headers":[],"relativePath":"classification/optical-phenomena/play-of-color.md","filePath":"classification/optical-phenomena/play-of-color.md","lastUpdated":1789230763000}'),n={name:"classification/optical-phenomena/play-of-color.md"};function i(l,e,s,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="play-of-color" tabindex="-1">Play of Color <a class="header-anchor" href="#play-of-color" aria-label="Permalink to &quot;Play of Color&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Play of color is opal&#39;s signature visual phenomenon. When white light enters ordered domains formed by silica spheres, different wavelengths diffract and interfere; changing the viewing angle shifts the spectral flashes across the surface. Strength, color range, and distribution depend on structural order, body tone, cut, and lighting.</p><h2 id="mechanism" tabindex="-1">Mechanism <a class="header-anchor" href="#mechanism" aria-label="Permalink to &quot;Mechanism&quot;">​</a></h2><p>Diffraction and interference within ordered silica-sphere domains create angle-dependent spectral flashes. As the viewing direction changes, different wavelengths are reinforced or suppressed, so the visible color pattern appears to move. “Play of color” describes the appearance, not a base body color or a single-source sparkle.</p><h2 id="example-gemstones" tabindex="-1">Example Gemstones <a class="header-anchor" href="#example-gemstones" aria-label="Permalink to &quot;Example Gemstones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Microstructure</th><th>Color Expression</th></tr></thead><tbody><tr><td>Precious Opal / 贵欧泊</td><td>ordered silica-sphere domains</td><td>angular spectral flashes</td></tr><tr><td>Black Opal / 黑欧泊</td><td>dark body tone + silica-sphere domains</td><td>red, green, blue</td></tr><tr><td>White Opal / 白欧泊</td><td>silica-sphere domains</td><td>green, blue, orange</td></tr></tbody></table><p><em>See the <a href="./intro.html">optical phenomena overview</a>.</em></p>',8)])])}const m=a(n,[["render",i]]);export{f as __pageData,m as default};
